import { useEffect, useMemo, useState } from "react";
import { ChevronDown, ChevronRight, Download, FileSpreadsheet, RefreshCw, ShieldAlert, Wrench } from "lucide-react";
import { downloadFile, fetchVulnerabilities, refreshVulnerabilities, vulnerabilityReportUrl } from "./api";

const LEVELS = [
  { key: "critical", short: "C", label: "Critical" },
  { key: "high", short: "H", label: "High" },
  { key: "medium", short: "M", label: "Medium" },
  { key: "low", short: "L", label: "Low" }
];

const SLOW_POLL_MS = 5 * 60 * 1000;
const LOADING_POLL_MS = 4000;
const RETRY_POLL_MS = 10000;

const STATUS_TEXT = {
  NO_RELEASE: "no release",
  NOT_SCANNED: "not scanned",
  TAG_NOT_FOUND: "release not found",
  PENDING: "pending",
  ERROR: "error"
};

function Chips({ counts }) {
  return (
    <span className="vuln-chips">
      {LEVELS.map((level) => (
        <span key={level.key} className={`vuln-chip ${level.key} ${counts[level.key] === 0 ? "zero" : ""}`} title={`${level.label}: ${counts[level.key]}`}>
          {counts[level.key]}
        </span>
      ))}
    </span>
  );
}

function formatTime(iso) {
  if (!iso) {
    return "";
  }
  const date = new Date(iso);
  return Number.isNaN(date.getTime()) ? "" : date.toLocaleString();
}

export default function VulnerabilityPanel({ onFixProject }) {
  const [summary, setSummary] = useState(null);
  const [loadError, setLoadError] = useState("");
  const [expanded, setExpanded] = useState(() => new Set());
  const [filter, setFilter] = useState("");
  const [showProjects, setShowProjects] = useState(false);
  const [downloading, setDownloading] = useState("");
  const [notice, setNotice] = useState("");

  // Loads at page load and keeps polling: fast while the backend is still loading, slow afterwards.
  useEffect(() => {
    let cancelled = false;
    let timer;

    async function load() {
      let delay = RETRY_POLL_MS;
      try {
        const data = await fetchVulnerabilities();
        if (cancelled) {
          return;
        }
        setSummary(data);
        setLoadError("");
        delay = data.state === "READY" ? SLOW_POLL_MS : data.state === "ERROR" ? 30000 : LOADING_POLL_MS;
      } catch (error) {
        if (cancelled) {
          return;
        }
        setLoadError(error instanceof Error ? error.message : "Backend not reachable");
      }
      timer = setTimeout(load, delay);
    }

    load();
    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, []);

  const projects = useMemo(() => {
    const list = summary?.projects || [];
    const needle = filter.trim().toLowerCase();
    if (!needle) {
      return list;
    }
    return list
      .map((project) => {
        if (project.project.toLowerCase().includes(needle)) {
          return project;
        }
        const modules = project.modules.filter((module) => module.module.toLowerCase().includes(needle));
        return modules.length > 0 ? { ...project, modules } : null;
      })
      .filter(Boolean);
  }, [summary, filter]);

  function toggle(name) {
    setExpanded((current) => {
      const next = new Set(current);
      if (next.has(name)) {
        next.delete(name);
      } else {
        next.add(name);
      }
      return next;
    });
  }

  async function download(key, params, fallbackName) {
    if (downloading) {
      return;
    }
    setDownloading(key);
    setNotice("");
    try {
      await downloadFile(vulnerabilityReportUrl(params), fallbackName);
    } catch (error) {
      setNotice(`Download failed: ${error instanceof Error ? error.message : "unknown error"}`);
    } finally {
      setDownloading("");
    }
  }

  async function reload() {
    setNotice("");
    try {
      setSummary(await refreshVulnerabilities());
    } catch (error) {
      setNotice(`Refresh failed: ${error instanceof Error ? error.message : "unknown error"}`);
    }
  }

  const state = summary?.state;
  const working = state === "LOADING" || state === "REFRESHING";
  const hasData = (summary?.projects || []).length > 0;
  const progress = summary && summary.total > 0 ? Math.min(100, Math.round((summary.done / summary.total) * 100)) : 0;

  return (
    <section className="vuln-panel">
      <div className="vuln-header">
        <div className="vuln-title"><ShieldAlert size={16} /> Vulnerabilities</div>
        <button type="button" className="vuln-icon-btn" onClick={reload} disabled={working} title="Reload from JFrog Xray" aria-label="Reload vulnerabilities">
          <RefreshCw size={14} className={working ? "spin" : ""} />
        </button>
      </div>
      <div className="vuln-sub">Latest release of every integration (JFrog Xray)</div>

      {loadError && !summary && <div className="vuln-message error">Backend not reachable: {loadError}. Retrying...</div>}
      {loadError && summary && <div className="vuln-message warn">Backend not reachable, showing last data.</div>}

      {state === "ERROR" && <div className="vuln-message error">{summary.message || "Vulnerability data could not be loaded."}</div>}

      {working && (
        <div className="vuln-progress">
          <div className="vuln-progress-text">
            {state === "LOADING" ? "Loading from JFrog Xray" : "Refreshing"}
            {summary.total > 0 ? ` - ${summary.done} of ${summary.total} modules` : "..."}
          </div>
          <div className="vuln-progress-bar"><div style={{ width: `${progress}%` }} /></div>
        </div>
      )}

      {!summary && !loadError && <div className="vuln-message">Loading...</div>}

      {hasData && (
        <>
          <div className="vuln-total">
            <div className="vuln-total-head">
              <span>Total</span>
              <strong>{summary.totals.total}</strong>
            </div>
            <div className="vuln-grid">
              {LEVELS.map((level) => (
                <div key={level.key} className={`vuln-cell ${level.key}`}>
                  <span className="num">{summary.totals[level.key]}</span>
                  <span className="lbl">{level.label}</span>
                </div>
              ))}
            </div>
            <div className="vuln-meta">
              {summary.projectCount} projects, {summary.moduleCount} modules, {summary.scannedModules} scanned
              {summary.generatedAt ? ` - ${formatTime(summary.generatedAt)}` : ""}
            </div>
            <div className="vuln-actions">
              <button type="button" className="vuln-btn" disabled={Boolean(downloading)} onClick={() => download("all", {}, "vulnerability-summary.csv")}>
                <Download size={13} /> {downloading === "all" ? "Preparing..." : "All projects (CSV)"}
              </button>
              <button type="button" className="vuln-btn" disabled={Boolean(downloading)} onClick={() => download("all-detail", { detail: true }, "vulnerability-details.csv")}>
                <FileSpreadsheet size={13} /> {downloading === "all-detail" ? "Preparing..." : "With CVEs"}
              </button>
            </div>
          </div>

          <button type="button" className="ctx-more vuln-expand" onClick={() => setShowProjects((value) => !value)} aria-expanded={showProjects}>
            {showProjects ? <ChevronDown size={12} /> : <ChevronRight size={12} />}
            {showProjects ? "Hide project-wise" : `Expand project-wise (${(summary.projects || []).length})`}
          </button>

          {showProjects && (<>
          <input
            className="vuln-filter"
            value={filter}
            onChange={(event) => setFilter(event.target.value)}
            placeholder="Filter project or module"
            aria-label="Filter projects"
          />

          <div className="vuln-projects">
            {projects.map((project) => {
              const open = expanded.has(project.project) || (filter.trim() !== "" && project.modules.length > 0);
              return (
                <div key={project.project} className="vuln-project">
                  <div className="vuln-project-row">
                    <button type="button" className="vuln-project-main" onClick={() => toggle(project.project)} aria-expanded={open}>
                      {open ? <ChevronDown size={15} /> : <ChevronRight size={15} />}
                      <span className="vuln-project-name">{project.project}</span>
                      {project.release && <span className="vuln-release">{project.release}</span>}
                    </button>
                    <span className="vuln-project-total" title="Total vulnerabilities of the project">
                      {project.scannedModules > 0 ? project.totals.total : "-"}
                    </span>
                    <button
                      type="button"
                      className="vuln-icon-btn"
                      disabled={Boolean(downloading)}
                      onClick={() => download(`p-${project.project}`, { project: project.project }, `vulnerability-${project.project}.csv`)}
                      title={`Download report of ${project.project}`}
                      aria-label={`Download report of ${project.project}`}
                    >
                      <Download size={14} />
                    </button>
                  </div>
                  {project.scannedModules > 0 && (
                    <div className="vuln-project-chips">
                      <Chips counts={project.totals} />
                      <span className="vuln-modules-count">{project.scannedModules}/{project.moduleCount} modules scanned</span>
                    </div>
                  )}

                  {open && (
                    <div className="vuln-modules">
                      <div className="vuln-module head">
                        <span>Module</span>
                        {LEVELS.map((level) => <span key={level.key} className={`num ${level.key}`} title={level.label}>{level.short}</span>)}
                        <span className="num">Tot</span>
                      </div>
                      {project.modules.map((module) => (
                        <div key={module.module} className="vuln-module" title={module.message || ""}>
                          <span className="vuln-module-name">
                            {module.module}
                            {module.version && <em>{module.version}{module.message && module.status === "OK" ? " *" : ""}</em>}
                          </span>
                          {module.status === "OK" ? (
                            <>
                              {LEVELS.map((level) => (
                                <span key={level.key} className={`num ${level.key} ${module.counts[level.key] === 0 ? "zero" : ""}`}>{module.counts[level.key]}</span>
                              ))}
                              <span className="num total">{module.counts.total}</span>
                            </>
                          ) : (
                            <span className="vuln-module-status">{STATUS_TEXT[module.status] || module.status}</span>
                          )}
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              );
            })}
            {projects.length === 0 && <div className="vuln-message">No project or module matches the filter.</div>}
          </div>
          <div className="vuln-legend">C critical, H high, M medium, L low. * latest release not yet indexed by Xray, older release shown.</div>
          </>)}
        </>
      )}

      {notice && <div className="vuln-message error">{notice}</div>}
    </section>
  );
}
